WITH base AS (SELECT * FROM products WHERE brand != 'Globex' AND supplier_id IS NOT NULL), cost_bucket_summary AS (SELECT CASE WHEN cost >= 560 THEN 'high' WHEN cost >= 340 THEN 'mid' ELSE 'low' END AS cost_bucket, category, MIN(stock_qty) AS min_stock_qty FROM base GROUP BY CASE WHEN cost >= 560 THEN 'high' WHEN cost >= 340 THEN 'mid' ELSE 'low' END, category) SELECT cost_bucket, category, min_stock_qty FROM cost_bucket_summary ORDER BY min_stock_qty DESC, category, cost_bucket LIMIT 50
